<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Notifications"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $s=admin_data('notifications.json',[]);if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();foreach(['enabled','newPostBlink','browserPrompt','sound'] as $k)$s[$k]=bool_post($k);admin_save('notifications.json',$s); write_json(SITE_ROOT.'/data/notifications.json',$s);flash('success','Notification settings saved.');redirect_admin('notifications.php');}?><div class="card"><div class="card-header"><h3 class="card-title">Post Notification Controls</h3></div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><?php foreach(['enabled'=>'Enable notification system','newPostBlink'=>'Blink NEW badge for latest posts','browserPrompt'=>'Show browser notification permission button','sound'=>'Sound notification'] as $id=>$lab):?><div class="custom-control custom-switch mb-3"><input class="custom-control-input" id="<?=$id?>" type="checkbox" name="<?=$id?>" <?=!empty($s[$id])?'checked':''?>><label class="custom-control-label" for="<?=$id?>"><?=$lab?></label></div><?php endforeach;?><button class="btn btn-pink">Save Notification Settings</button></form></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>